import { useEffect, useRef, useState } from 'react';

export const CardConnector = ({
  startRef,
  endRef,
  startOffset = { x: 0, y: 0 },
  endOffset = { x: 0, y: 0 },
  type = 'auto',
  lineColor = 'white',
  strokeWidth = 2,
  segmentLength = 60,
  className = '',
  zIndex = 0,
  zAngle,
  startLineLengthCoefficient = 1,
  endLineLengthCoefficient = 1,
  segments = null, // Новый параметр: массив сегментов segments={[{ length: 30, angle: 90 }, { length: 30, angle: 0 }]}
}) => {
  const [paths, setPaths] = useState([]);
  const svgRef = useRef(null);

  const updateLine = () => {
    if (!startRef.current || !svgRef.current) return;

    const startBox = startRef.current.getBoundingClientRect();
    const svgBox = svgRef.current.getBoundingClientRect();

    const startX = startBox.left - svgBox.left + startOffset.x;
    const startY = startBox.top - svgBox.top + startOffset.y;

    // --- Новый режим: если segments передан ---
    if (Array.isArray(segments) && segments.length > 0) {
      let x = startX;
      let y = startY;
      let currentAngle = 0;
      let pathArr = [];
      let prevX = x;
      let prevY = y;

      segments.forEach((seg, i) => {
        const color = seg.color || lineColor;
        currentAngle += seg.angle; // угол относительно предыдущего сегмента
        const rad = (currentAngle * Math.PI) / 180;
        const nextX = prevX + Math.cos(rad) * seg.length;
        const nextY = prevY + Math.sin(rad) * seg.length;
        pathArr.push({
          d: `M ${prevX},${prevY} L ${nextX},${nextY}`,
          color,
        });
        prevX = nextX;
        prevY = nextY;
      });

      setPaths(pathArr);
      return;
    }

    // --- Старая логика: если segments не передан ---
    let path = '';

    // Если нет конечной точки — до правого края SVG
    if (!endRef?.current) {
      const svgWidth = svgRef.current.clientWidth || svgRef.current.getBoundingClientRect().width;

      switch (type) {
        case 'straight':
        case 'horizontal':
          path = `M ${startX},${startY} L ${svgWidth},${startY}`;
          break;
        case 'vertical': {
          const svgHeight =
            svgRef.current.clientHeight || svgRef.current.getBoundingClientRect().height;
          path = `M ${startX},${startY} L ${startX},${svgHeight}`;
          break;
        }
        default:
          path = `M ${startX},${startY} L ${svgWidth},${startY}`;
      }
    } else {
      const endBox = endRef.current.getBoundingClientRect();
      const endX = endBox.left - svgBox.left + endOffset.x;
      const endY = endBox.top - svgBox.top + endOffset.y;

      switch (type) {
        case 'straight':
          path = `M ${startX},${startY} L ${endX},${endY}`;
          break;
        case 'horizontal':
          path = `M ${startX},${startY} L ${endX},${startY}`;
          break;
        case 'vertical':
          path = `M ${startX},${startY} L ${startX},${endY}`;
          break;
        case 'l':
          path = `M ${startX},${startY} L ${endX},${startY} L ${endX},${endY}`;
          break;
        case 'r':
          path = `M ${startX},${startY} L ${startX},${endY} L ${endX},${endY}`;
          break;
        case 'z': {
          const deltaX = endX - startX;
          const deltaY = endY - startY;
          const maxSegment = Math.abs(deltaX / 2);
          const safeSegment = Math.min(segmentLength, maxSegment);

          const firstSegment = safeSegment * startLineLengthCoefficient;
          const secondSegment = safeSegment * endLineLengthCoefficient;
          const sign = deltaX >= 0 ? 1 : -1;

          // --- Новая логика: если zAngle задан ---
          if (typeof zAngle === 'number') {
            // zAngle: 90 (вниз), -90 (вверх), 0 (вправо), 180 (влево)
            // Первый сегмент — горизонтальный, второй — вертикальный под углом zAngle
            // (или наоборот, если хочешь)
            const angleRad = (zAngle * Math.PI) / 180;
            // Первый излом: идём по X (горизонталь)
            const point1X = startX + sign * firstSegment;
            const point1Y = startY;
            // Второй излом: идём по Y (вертикаль) с учётом знака угла
            const point2X = point1X;
            const point2Y = endY;

            path = `
      M ${startX},${startY}
      L ${point1X},${point1Y}
      L ${point2X},${point2Y}
      L ${endX},${endY}
    `.trim();
          } else {
            // --- Старая логика ---
            const point1X = startX + sign * firstSegment;
            const point1Y = startY;
            const point2X = endX - sign * secondSegment;
            const point2Y = endY;
            path = `
      M ${startX},${startY}
      L ${point1X},${point1Y}
      L ${point2X},${point2Y}
      L ${endX},${endY}
    `.trim();
          }
          break;
        }
        case 'auto':
        default: {
          const deltaX = endX - startX;
          const deltaY = endY - startY;
          const maxSegment = Math.abs(deltaX / 2);
          const safeSegment = Math.min(segmentLength, maxSegment);

          const firstSegment = safeSegment * startLineLengthCoefficient;
          const secondSegment = safeSegment * endLineLengthCoefficient;
          const sign = deltaX >= 0 ? 1 : -1;

          if (Math.abs(deltaX) > Math.abs(deltaY)) {
            const point1X = startX + sign * firstSegment;
            const point1Y = startY;
            const point2X = endX - sign * secondSegment;
            const point2Y = endY;

            path = `
              M ${startX},${startY}
              L ${point1X},${point1Y}
              L ${point2X},${point2Y}
              L ${endX},${endY}
            `.trim();
          } else {
            const point1X = startX;
            const point1Y = startY + sign * firstSegment;
            const point2X = endX;
            const point2Y = endY - sign * secondSegment;

            path = `
              M ${startX},${startY}
              L ${point1X},${point1Y}
              L ${point2X},${point2Y}
              L ${endX},${endY}
            `.trim();
          }
          break;
        }
      }
    }

    setPaths([{ d: path, color: lineColor }]);
  };

  useEffect(() => {
    updateLine();
    window.addEventListener('resize', updateLine);
    return () => window.removeEventListener('resize', updateLine);
    // eslint-disable-next-line
  }, [
    type,
    lineColor,
    strokeWidth,
    segmentLength,
    startLineLengthCoefficient,
    endLineLengthCoefficient,
    segments,
  ]);

  useEffect(() => {
    const interval = setInterval(updateLine, 100);
    return () => clearInterval(interval);
    // eslint-disable-next-line
  }, [segments, type, startRef, endRef, startOffset, endOffset]);

  return (
    <svg
      ref={svgRef}
      className={className}
      style={{
        position: 'absolute',
        top: 0,
        left: 0,
        width: '100%',
        height: '100%',
        zIndex: zIndex,
        pointerEvents: 'none',
        overflow: 'visible',
      }}
    >
      {paths.map((seg, i) => (
        <path key={i} d={seg.d} stroke={seg.color} strokeWidth={strokeWidth} fill="none" />
      ))}
    </svg>
  );
};
