/**
 * Хук useButtonActive
 *
 * Используется для отслеживания состояния "активной" кнопки
 * с поддержкой как мышиных, так и клавиатурных событий.
 *
 * Поддерживаемые события:
 * - `onMouseDown` / `onMouseUp` / `onMouseLeave` — клики мышью
 * - `onKeyDown` / `onKeyUp` — клавиши Enter и Space
 *
 * Хук полезен, если нужно стилизовать кнопку при нажатии или удерживании,
 * например, для визуального отклика при клике или доступном взаимодействии с клавиатуры.
 *
 * @returns {{
 *   isActive: boolean,                            // Состояние активности кнопки
 *   buttonEvents: {                               // Обработчики событий для привязки к элементу
 *     onMouseDown: () => void,
 *     onMouseUp: () => void,
 *     onMouseLeave: () => void,
 *     onKeyDown: (e: KeyboardEvent) => void,
 *     onKeyUp: (e: KeyboardEvent) => void,
 *   }
 * }}
 *
 * @example
 * const { isActive, buttonEvents } = useButtonActive();
 * return (
 *   <button {...buttonEvents} className={isActive ? 'active' : ''}>
 *     Нажми меня
 *   </button>
 * );
 */

import { useState } from 'react';

export const useButtonActive = () => {
  const [isActive, setIsActive] = useState(false);

  const onMouseDown = () => setIsActive(true);
  const onMouseUp = () => setIsActive(false);
  const onMouseLeave = () => setIsActive(false);
  const onKeyDown = (e) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      setIsActive(true);
    }
  };
  const onKeyUp = (e) => {
    if (e.key === 'Enter' || e.key === ' ') {
      setIsActive(false);
    }
  };

  return {
    isActive,
    buttonEvents: {
      onMouseDown,
      onMouseUp,
      onMouseLeave,
      onKeyDown,
      onKeyUp,
    },
  };
};
