import Marquee from 'react-fast-marquee';

function textToBinary(str) {
  return (
    str
      .split('')
      .map((char) => char.charCodeAt(0).toString(2).padStart(8, '0'))
      .join(' ') + ' '
  );
}

function randomBinaryString(length) {
  let s = '';
  for (let i = 0; i < length; i++) {
    s += Math.random() > 0.5 ? '1' : '0';
    if ((i + 1) % 8 === 0 && i !== length - 1) {
      s += ' ';
    }
  }
  return s;
}

export function BinaryRain({
  rows = 8,
  length = 32,
  color = '#00ffcc',
  speed = 40, // px/sec
  highlightText = '',
  highlightColor = '#fff',
  fontSize = '0.32vw',
  fontFamily = 'Roboto, monospace',
  background = '#000000',
  style = {},
}) {
  length = Math.ceil(length / 8) * 8;

  return (
    <div
      style={{
        width: '100%',
        height: '100%',
        background,
        overflow: 'hidden',
        paddingLeft: '2px',
        paddingRight: '5px',
        boxSizing: 'border-box',
        fontWeight: 'bold',
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'center',
        gap: '0.01em',
        ...style,
      }}
    >
      {Array.from({ length: rows }).map((_, i) => {
        const isHighlight = highlightText && i === Math.floor(rows / 2);
        const text = isHighlight ? textToBinary(highlightText) : randomBinaryString(length);

        return (
          <Marquee
            key={i}
            gradient={false}
            speed={speed + (isHighlight ? 0 : Math.random() * 10)}
            pauseOnHover={false}
            style={{
              width: '100%',
              fontFamily,
              fontSize,
              color: isHighlight ? highlightColor : color,
              lineHeight: '150%',
              height: '1.65em',
              fontWeight: '500',
              userSelect: 'none',
              whiteSpace: 'pre',
            }}
          >
            {text + '   '}
          </Marquee>
        );
      })}
    </div>
  );
}
