import { useEffect, useState } from 'react';
import { useForm, useWatch } from 'react-hook-form';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';

import { Loading } from '../../../../components/Loading';
import { emailValidation, passwordValidation } from '../../../../helpers/validationRules';
import { fetchLoginRequest } from '../../../../redux/slices/loginSlice';
import {
  FormErrorMessage,
  GradientBorderBox,
  gradientList,
  PasswordVisibilityToggle,
  Button,
} from '@/shared/ui';
import { useButtonActive } from '@/shared/lib/hooks';

import styles from './LoginForm.module.css';

/**
 * Компонент LoginForm — форма аутентификации пользователя.
 *
 * Содержит поля:
 * - Email
 * - Пароль с возможностью показать/скрыть
 *
 * Интеграция с:
 * - React Hook Form — управление формой и валидацией
 * - Redux — авторизация через dispatch
 * - React Router — редирект при успехе
 *
 * Возможности:
 * - Переключение на регистрацию (onRegisterClick)
 * - Закрытие формы при входе (onClose)
 * - Кастомный UI с градиентной рамкой
 *
 * @param {Object} props
 * @param {() => void} props.onClose - Закрытие формы логина после входа
 * @param {() => void} props.onRegisterClick - Переключение на форму регистрации
 *
 * @returns {JSX.Element} Визуальный компонент формы входа с двумя кнопками
 *
 * @example <LoginForm onClose={...} onRegisterClick={...} />
 */

export const LoginForm = ({ onClose, onRegisterClick }) => {
  const { isLoggedIn, isLoading, error: serverError } = useSelector((state) => state.login);
  const [user, setUser] = useState({
    login: '',
    password: '',
  });
  const [showPassword, setShowPassword] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [isButtonActive, setIsButtonActive] = useState(false);
  const { isActive: isLoginActive, buttonEvents: loginEvents } = useButtonActive();
  const { isActive: isRegisterActive, buttonEvents: registerEvents } = useButtonActive();
  const {
    register,
    handleSubmit,
    setError,
    clearErrors,
    control,
    formState: { errors },
  } = useForm();
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const watch = useWatch({ control });

  useEffect(() => {
    if (serverError) {
      clearErrors(); // очищает все ошибки
    }
  }, [watch.login, watch.password]);

  useEffect(() => {
    if (isLoggedIn) {
      onClose();
      navigate('/profile');
    }
  }, [isLoggedIn]); //navigate

  useEffect(() => {
    if (serverError) {
      setError('login', {
        type: 'server',
        message: serverError,
      });

      setError('password', {
        type: 'server',
        message: serverError,
      });
    }
  }, [serverError, setError]);

  const handleButtonClick = () => {
    setIsButtonActive(true);
    setTimeout(() => {
      setIsButtonActive(false);
    }, 200);
  };

  const handleLoginSubmit = () => {
    setShowForm(false);
  };

  const openRegisterForm = () => {
    onRegisterClick();
  };

  const onSubmit = (data) => {
    dispatch(fetchLoginRequest(data));
  };

  return (
    <>
      {isLoading ? (
        <Loading />
      ) : (
        <div className={styles.wrapper}>
          <div className={styles.container}>
            <h1 className={styles.title}>Вход в личный кабинет</h1>
            <form id="authForm" className={styles.authForm} onSubmit={handleSubmit(onSubmit)}>
              {/* Email */}
              <div className={styles.formGroup}>
                <label htmlFor="email" className={styles.formLabel}>
                  Login
                </label>
                <GradientBorderBox
                  gradient={errors.email ? gradientList.input.error : gradientList.input.default}
                >
                  <input
                    type="text"
                    id="login" //email
                    {...register('login', emailValidation)}
                    className={styles.formInput}
                    placeholder="Введите ваш email"
                    autoComplete="email"
                  />
                </GradientBorderBox>
                <FormErrorMessage name="email" errors={errors} />
              </div>

              {/* Password */}
              <div className={styles.formGroup}>
                <label htmlFor="password" className={styles.formLabel}>
                  Пароль
                </label>
                <div className={styles.inputContainer}>
                  <GradientBorderBox
                    gradient={
                      errors.password ? gradientList.input.error : gradientList.input.default
                    }
                  >
                    <input
                      type={showPassword ? 'text' : 'password'}
                      id="password"
                      {...register('password', passwordValidation)}
                      className={styles.formInput}
                      placeholder="Введите ваш пароль"
                      autoComplete="password"
                    />
                  </GradientBorderBox>

                  {/* Переключатель видимости пароля */}
                  <PasswordVisibilityToggle
                    visible={showPassword}
                    onToggle={() => setShowPassword((v) => !v)}
                  />
                </div>
                <FormErrorMessage name="password" errors={errors} />
              </div>
              <div className={styles.buttonContainer}>
                {/* Кнопка входа */}
                <GradientBorderBox
                  gradient={
                    isLoginActive ? gradientList.button.active : gradientList.button.default
                  }
                >
                  <Button
                    type="submit"
                    className={styles.loginButton}
                    {...loginEvents}
                    onClick={handleLoginSubmit}
                  >
                    Войти
                  </Button>
                </GradientBorderBox>

                {/* Кнопка регистрации */}
                <GradientBorderBox
                  gradient={
                    isRegisterActive ? gradientList.button.active : gradientList.button.default
                  }
                >
                  <Button
                    type="button"
                    className={styles.registerButton}
                    {...registerEvents}
                    onClick={openRegisterForm}
                  >
                    Зарегистрироваться
                  </Button>
                </GradientBorderBox>
              </div>
            </form>
          </div>
        </div>
      )}
    </>
  );
};
