import { Link } from 'react-router-dom';

import styles from './Button.module.css';

/**
 * Многофункциональный компонент кнопки с поддержкой переходов и ссылок.
 *
 * Адаптируется под:
 * - `<button>` для действий
 * - `<a>` для внешних ссылок
 * - `<Link>` из react-router-dom для внутренней навигации
 *
 * @param {Object} props
 * @param {React.ReactNode} props.children - Содержимое кнопки
 * @param {string} [props.to] - Путь для <Link>
 * @param {string} [props.href] - URL для <a>
 * @param {() => void} [props.onClick] - Обработчик клика
 * @param {'light' | 'dark'} [props.frame] - Цветовая тема
 * @param {string} [props.type] - Тип кнопки (submit, reset, button)
 * @param {string} [props.form] - ID формы, если используется вне формы
 * @param {boolean} [props.disabled] - Состояние disabling
 * @param {string} [props.className] - Кастомный CSS-класс
 * @param {Object} [props.style] - Inline-стили
 * @param {number|string} [props.width] - Ширина кнопки
 * @param {number|string} [props.height] - Высота кнопки
 *
 * @returns {JSX.Element}
 */

export const Button = ({
  children,
  to,
  href,
  type = 'button',
  form,
  onClick,
  disabled,
  width,
  height,
  style,
  frame = 'light', // 'light' или 'dark'
  className,
  ...rest
}) => {
  const buttonStyle = { width, height, ...style };
  const frameClass = frame === 'dark' ? styles.dark : '';
  // Обработчик для имитации клика по Enter/Space
  const handleKeyDown = (e) => {
    if (disabled) return;
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      if (onClick) onClick(e);
    }
  };

  if (to) {
    return (
      <Link
        to={to}
        className={`${styles.button} ${frameClass} ${className}`}
        style={buttonStyle}
        role="button"
        tabIndex={disabled ? -1 : 0}
        aria-disabled={disabled}
        onClick={disabled ? (e) => e.preventDefault() : onClick}
        onKeyDown={handleKeyDown}
        {...rest}
      >
        <span className={styles.buttonText}>{children}</span>
      </Link>
    );
  }

  if (href) {
    return (
      <a
        href={disabled ? undefined : href}
        className={`${styles.button} ${frameClass} ${className}`}
        style={buttonStyle}
        role="button"
        tabIndex={disabled ? -1 : 0}
        aria-disabled={disabled}
        onClick={disabled ? (e) => e.preventDefault() : onClick}
        onKeyDown={handleKeyDown}
        {...rest}
      >
        <span className={styles.buttonText}>{children}</span>
      </a>
    );
  }

  return (
    <button
      type={type}
      form={form}
      onClick={onClick}
      disabled={disabled}
      className={`${styles.button} ${className}`}
      style={buttonStyle}
      {...rest}
    >
      <span className={styles.buttonText}>{children}</span>
    </button>
  );
};
