import { useEffect, useRef, useState } from 'react';

import styles from './DropdownTabs.module.css';

export const DropdownTabs = ({ indicator, title, options = [], onChange }) => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [selected, setSelected] = useState(0);
  const containerRef = useRef(null);

  const handleClick = (index) => {
    setSelected(index);
    if (onChange) onChange(options[index]);
  };

  // Закрытие по клику вне меню
  useEffect(() => {
    const handleClickOutside = (e) => {
      if (containerRef.current && !containerRef.current.contains(e.target)) {
        setIsMenuOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <div className={styles.menuWrapper}>
      <div className={styles.menuTitle}>{title}</div>

      <div
        ref={containerRef}
        className={styles.menuContainer}
        onMouseEnter={() => setIsMenuOpen(true)}
        onMouseLeave={() => setIsMenuOpen(false)}
      >
        <div className={`${styles.menuBox} ${isMenuOpen ? styles.menuBoxOpen : ''}`}>
          <div className={styles.selectedOption}>
            <div className={styles.option}>
              {indicator ? (
                <div className={styles.indicator} style={{ backgroundColor: indicator }}></div>
              ) : null}
              <span className={styles.optionName}>{options[selected]}</span>
            </div>
            <span className={`${styles.arrow} ${isMenuOpen ? styles.arrowOpen : ''}`}></span>
          </div>

          <ul
            className={`${styles.menu} ${isMenuOpen ? styles.menuVisible : ''}`}
            aria-hidden={!isMenuOpen}
          >
            {options.map((option, index) => (
              <li key={index} className={styles.menuItem}>
                <button
                  className={`${styles.tabButton} ${selected === index ? styles.active : ''}`}
                  onClick={() => handleClick(index)}
                >
                  {option}
                </button>
              </li>
            ))}
          </ul>
        </div>
      </div>
    </div>
  );
};
