import React from 'react';

import styles from './Sidebar.module.css';

// Пункты меню
const menuItems = [
  { id: 'account', label: 'Ваш аккаунт', icon: '/icon/account.svg' },
  { id: 'demo', label: 'Демо счет', icon: '/icon/demo.svg' },
  { id: 'trade', label: 'Торговля', icon: '/icon/trade.svg' },
  { id: 'strategies', label: 'Стратегии', icon: '/icon/strategies.svg' },
  { id: 'affiliate', label: 'Партнерская программа', icon: '/icon/affiliate.svg' },
];

export const Sidebar = ({ activeSection, setActiveSection }) => {
  return (
    <nav className={styles.sidebar}>
      <ul className={styles.menuList}>
        {menuItems.map((item) => {
          const isActive = activeSection === item.id;
          const iconPath = isActive ? item.icon.replace('.svg', '_active.svg') : item.icon;

          return (
            <li
              key={item.id}
              className={`${styles.menuItem} ${isActive ? styles.active : ''}`}
              onClick={() => setActiveSection(item.id)}
            >
              <div className={styles.icon}>
                <img src={iconPath} alt={item.label} />
              </div>
              <div className={styles.menuText}>{item.label}</div>
            </li>
          );
        })}
      </ul>
    </nav>
  );
};
