import React, { useState } from 'react';

import styles from './AIRecommendations.module.css';

export const AIRecommendations = () => {
  const ideas = [
    {
      title: 'Идея 1',
      description: 'Использовать дополнительные пары в корзине',
      details:
        'Подробное описание идеи 1. Здесь может быть больше текста, аналитика, графики и т.д.',
    },
    {
      title: 'Идея 2',
      description: 'Сократить риски при помощи хеджирования',
      details: 'Подробное описание идеи 2.',
    },
    {
      title: 'Идея 3',
      description: 'Применить машинное обучение для анализа рынка',
      details: 'Подробное описание идеи 3.',
    },
    {
      title: 'Идея 4',
      description: 'Увеличить долю активов с высокой волатильностью',
      details: 'Подробное описание идеи 4.',
    },
    {
      title: 'Идея 5',
      description: 'Автоматизировать ребалансировку портфеля',
      details: 'Подробное описание идеи 5.',
    },
  ];

  const [selectedIdea, setSelectedIdea] = useState(null);

  const openModal = (idea) => {
    setSelectedIdea(idea);
  };

  const closeModal = () => {
    setSelectedIdea(null);
  };

  return (
    <div className={styles.container}>
      <div className={styles.header}>
        <h2 className={styles.tytle}>Рекомендации от AI</h2>
      </div>
      <div className={styles.ideas}>
        {ideas.map((idea, index) => (
          <div className={styles.ideasCard} key={index}>
            <h3 className={styles.ideasTitle}>{idea.title}</h3>
            <span className={styles.ideasDescription}>{idea.description}</span>
            <button className={styles.ideasDetails} onClick={() => openModal(idea)}>
              Подробнее
            </button>
          </div>
        ))}
      </div>

      {selectedIdea && (
        <div className={styles.modalOverlay}>
          <div className={styles.modal}>
            <h3>{selectedIdea.title}</h3>
            <p>{selectedIdea.details}</p>
            <button className={styles.closeButton} onClick={closeModal}>
              Закрыть
            </button>
          </div>
        </div>
      )}
    </div>
  );
};
