import { MdVisibility, MdVisibilityOff } from 'react-icons/md';

import styles from './PasswordVisibilityToggle.module.css';

/**
 * Компонент визуального переключателя видимости пароля
 *
 * @param {Object} props
 * @param {boolean} visible - Показывается ли пароль в данный момент
 * @param {Function} onToggle - Колбэк переключения видимости
 * @returns {JSX.Element}
 */
export const PasswordVisibilityToggle = ({ visible, onToggle }) => {
  const handleKeyDown = (e) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      onToggle();
    }
  };

  return (
    <span
      className={styles.visibilityToggle}
      onClick={onToggle}
      tabIndex={0}
      role="button"
      aria-label={visible ? 'Скрыть пароль' : 'Показать пароль'}
      onKeyDown={handleKeyDown}
    >
      {visible ? <MdVisibility /> : <MdVisibilityOff />}
    </span>
  );
};
