import React, { useEffect, useState } from 'react';
import {
  Area,
  AreaChart,
  CartesianGrid,
  Legend,
  ReferenceLine,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from 'recharts';

import { DropdownTabs } from '../DropdownTabs';

import styles from './TrendAreaChart.module.css';

const CustomTooltip = ({ active, payload, label }) => {
  if (active && payload && payload.length) {
    return (
      <div
        style={{
          backgroundColor: '#222',
          border: '1px solid #444',
          borderRadius: '8px',
          padding: '10px',
          color: '#fff',
          fontSize: '10px',
        }}
      >
        <p>{`${label}`}</p>
        {payload.map((entry, index) => {
          if (entry.name === 'BTC' && typeof entry.value === 'undefined') return null;

          return (
            <p key={index} style={{ color: entry.color }}>
              {entry.name}: {entry.value}
            </p>
          );
        })}
      </div>
    );
  }

  return null;
};

